// History, change over time and the forecast, in the team's words (translated from Russian): "from the
// growth it sees that ... the readings will no longer be within the norm".
// Code generated by Claude (Anthropic), an AI system.
//
// How it works, step by step:
// 1. Take one person's readings of one measure, in time order.
// 2. Draw the straight line that passes closest to those readings (least squares). Its slope says
//    whether the measure goes up, goes down or stays flat, and how fast per day.
// 3. Carry that line forward in time and find the first day it crosses a border of the norm.
//    That day is the forecast. If the line never crosses before the date we look at, there is no crossing.
// The method is Claude's technical choice: the simplest honest way to "see the growth". It is not a
// validated medical model; real forecasts need tested models and doctors.

const DAY = 24 * 60 * 60 * 1000;

const toTime = (t) => (t instanceof Date ? t.getTime() : new Date(t).getTime());

// Least-squares straight line through points {t (ms), v}. Returns null with fewer than minPoints.
export function fitLine(points, { minPoints = 3 } = {}) {
  const pts = points.filter((p) => Number.isFinite(p.t) && Number.isFinite(p.v));
  if (pts.length < minPoints) return null;
  const t0 = pts[0].t;
  const xs = pts.map((p) => (p.t - t0) / DAY);
  const ys = pts.map((p) => p.v);
  const n = pts.length;
  const mx = xs.reduce((a, b) => a + b, 0) / n;
  const my = ys.reduce((a, b) => a + b, 0) / n;
  let sxx = 0;
  let sxy = 0;
  for (let i = 0; i < n; i += 1) {
    sxx += (xs[i] - mx) * (xs[i] - mx);
    sxy += (xs[i] - mx) * (ys[i] - my);
  }
  if (sxx === 0) return null; // all readings on the same day: no direction can be seen
  const perDay = sxy / sxx;
  const at = (t) => my + perDay * ((toTime(t) - t0) / DAY - mx);
  return { perDay, at, t0, n, from: pts[0].t, to: pts[n - 1].t };
}

// Which way the measure goes. A change smaller than `flatPerDay` per day counts as flat.
export function direction(line, flatPerDay) {
  if (!line) return 'unknown';
  if (Math.abs(line.perDay) <= flatPerDay) return 'flat';
  return line.perDay > 0 ? 'up' : 'down';
}

// First day after `from` when the line crosses a border of [min, max], looking up to `until`.
// Returns { side: 'below' | 'above', date } or null if it stays inside until then.
export function crossing(line, { min = null, max = null, maxExclusive = false }, from, until) {
  if (!line) return null;
  const start = toTime(from);
  const end = toTime(until);
  if (!(end > start)) return null;
  const inside = (v) => !((min !== null && v < min) || (max !== null && (maxExclusive ? v >= max : v > max)));
  if (!inside(line.at(start))) return { side: min !== null && line.at(start) < min ? 'below' : 'above', date: new Date(start), already: true };
  // Solve the straight line for each border; take the earliest crossing inside the window.
  const candidates = [];
  const tAt = (value) => line.t0 + ((value - line.at(line.t0)) / line.perDay) * DAY;
  if (line.perDay < 0 && min !== null) candidates.push({ side: 'below', t: tAt(min) });
  if (line.perDay > 0 && max !== null) candidates.push({ side: 'above', t: tAt(max) });
  const hit = candidates.filter((c) => c.t > start && c.t <= end).sort((a, b) => a.t - b.t)[0];
  return hit ? { side: hit.side, date: new Date(hit.t), already: false } : null;
}

// Everything for one person and one measure: the line, the direction, the forecast against the norm
// used in flight, and the value the line reaches on the planned landing day.
// A direction needs readings on at least `minDays` different days: readings taken minutes apart say
// nothing about weeks, and a line through them would shoot off.
// The crossing is looked for from the last reading on, so a border the line passes between the last
// reading and today is still seen (`crossedBeforeNow`).
export function forecast(history, { norm, flatPerDay, now, landing, window = null, minDays = 3 }) {
  const pts = history
    .filter((h) => h.value !== null && h.value !== '' && Number.isFinite(Number(h.value)))
    .map((h) => ({ t: toTime(h.time), v: Number(h.value) }))
    .filter((p) => Number.isFinite(p.t) && (!window || (p.t >= toTime(window.from) && p.t <= toTime(window.to))))
    .sort((a, b) => a.t - b.t);
  const days = new Set(pts.map((p) => Math.floor(p.t / DAY))).size;
  const line = days >= minDays ? fitLine(pts) : null;
  const dir = direction(line, flatPerDay);
  const cross = norm && line ? crossing(line, norm, line.to, landing) : null;
  const crossedBeforeNow = Boolean(cross && !cross.already && now && cross.date.getTime() <= toTime(now));
  const atLanding = line && landing ? line.at(landing) : null;
  return { points: pts.length, days, line, direction: dir, crossing: cross, crossedBeforeNow, atLanding };
}
